import json,shutil,xml.etree.ElementTree as ET
from pathlib import Path
def read(p):return json.loads(Path(p).read_text(encoding='utf8'))
def main():
    growth=read('reports/growth_40m.json');integrity=read('reports/capacity_integrity.json');after=read('reports/neral40m_full_test.json');raw=read('reports/neral40m_candidate_test.json');before=read('reports/human_comparison_02.json')['models']['pilot_02'];oldraw=read('reports/after_pilot_02.json')
    runs={}
    for name in ['neral40m_01','neral40m_capacity']:
        summary=read('runs/'+name+'/summary.json');events=[json.loads(l) for l in Path('runs/'+name+'/metrics.jsonl').read_text().splitlines()];runs[name]={'summary':summary,'run':read('runs/'+name+'/run.json'),'final_validation':events[-1]['validation'],'selected_updates':[r['step'] for r in events if r.get('selected')]}
    xml=ET.parse('reports/pytest_03.xml');tests=sum(int(s.attrib.get('tests',0)) for s in xml.iter('testsuite'));failed=sum(int(s.attrib.get('errors',0))+int(s.attrib.get('failures',0)) for s in xml.iter('testsuite'))
    result={'available':True,'before_label':'20M · Preview 02','after_label':'40M · Versuch','parameters_before':20587008,'parameters_after':40051200,'architecture_changed':True,'default_checkpoint':'pilot_02','promoted':False,'reason':'Neither controlled continuation improved macro validation loss. Best remained grown step 0; trained capacity-only step 100 is exposed as experimental comparison.','growth':growth,'runs':runs,'test':{'before':before['loss']['macro_loss'],'after':after['loss']['macro_loss'],'note':after['note']},'domains':[{'domain':d,'before':v['loss'],'after':after['loss']['domains'][d]['loss']} for d,v in before['loss']['domains'].items()],'math':{'before':oldraw['math_numeric_exact'],'after':raw['math_numeric_exact']},'tests':{'total':tests,'failed':failed},'integrity':integrity,'features':{'cascade':'preview, explicit apply, revision conflict prevention, undo','ripple':'full traversal of declared project dependencies, paths and direct dependencies','solve':'exact arithmetic and bounded linear equations with substitution check','living_answers':'local source-driven updates, immutable text versions and persisted history'},'limits':['Feature V1 uses explicit local graph rules; not capabilities learned by the language model.','Living Answers monitors local project changes only; no external sources or background web monitoring.','Only the immediately preceding CASCADE transaction can be undone; later edits require a new preview.','Small repeatedly inspected data; no evidence of broadly useful free chat.']}
    if not Path('reports/comparison_02.json').exists():shutil.copy2('reports/comparison.json','reports/comparison_02.json')
    Path('reports/comparison.json').write_text(json.dumps(result,ensure_ascii=False,indent=2),encoding='utf8')
    lines=['# Neral Preview 03 – eigenes 40M-Modell und erste Features','', '## Modell und Abstammung','**40.051.200 Parameter**, ausschließlich aus deinem eigenen Neral weiterentwickelt. Sechs Transformer-Blöcke, Modellbreite 512 und Byte-Tokenizer bleiben erhalten. Die FFN-Breite wächst von 1536 auf 3648. Kein fremder Checkpoint und keine Cloud-Inferenz. Modellcode und ursprünglicher Checkpoint bleiben erhalten.', '', 'Die vorhandenen Gewichte wurden kopiert. Neue Gate-/Up-Gewichte wurden lokal initialisiert, neue Down-Projektionen zunächst auf null gesetzt. Damit beginnt die größere Architektur mit praktisch derselben Funktion. Vor der Änderung wurde die 20M-Baseline erneut gemessen.',f'- Maximale FP32-Logit-Abweichung auf dem dokumentierten Probe-Tensor: {growth["max_abs_logit_difference_fp32"]:.9g}.',f'- BF16-Validation vor Erweiterung: {growth["before"]["macro_loss"]:.7f}; danach, vor Training: {growth["after_growth_before_training"]["macro_loss"]:.7f}.', '- Die erste BF16-Toleranz von 0,0001 war für die geänderte Matrixform geringfügig zu eng (Differenz rund 0,000131). Nach Prüfung des FP32-Vergleichs wurde die BF16-Grenze auf 0,01 gesetzt. Das ist ein numerischer Unterschied, kein gemessener Lerngewinn.', '', '## Tatsächlich ausgeführtes Training', 'Unveränderte Curriculum-v2-Splits: 1515 Training / 177 Validation / 155 Regressionstest. Antwortmaskierung, sechs Domänen, BF16 auf RTX 4070, effektive Batchgröße 32. Keine zusätzlichen Daten in diesem Durchlauf.','', '| Versuch | Updates | Stop | Letzte Validation | Zeit Trainingsschleife |','|---|---:|---|---:|---:|']
    for name,r in runs.items():lines.append(f'| {name} | {r["summary"]["completed_step"]} | {r["summary"]["stop_reason"]} | {r["final_validation"]["macro_loss"]:.5f} | {r["summary"]["elapsed_seconds"]:.2f} s |')
    lines += ['', 'Erster Lauf: alle Gewichte trainiert, LR 1e-5. Zweiter Lauf: nur die 19.464.192 neuen Parameter, LR 2e-5, kopierte Parameter durch Einfrieren/Gradientenmasken und deaktivierten Weight Decay unverändert. Beide hatten maximal 400 Updates, Evaluation alle 25 Updates und Geduld für vier Prüfungen ohne ausreichende Verbesserung.', '', '**Keiner der beiden Läufe verbessert den Macro-Validierungs-Loss.** Early-Stopping greift jeweils bei 100 Updates; die beste Bewertung bleibt beim erweiterten Ausgangszustand, Schritt 0. Deshalb bleibt Neral-20M Preview 02 der Standard. Der tatsächlich trainierte 40M-Kandidat aus dem zweiten Lauf ist bewusst als experimentelle Vergleichsoption verfügbar.', '', 'Die übernommenen Parameter des zweiten Kandidaten wurden nach dem Training bitgenau gegen Preview 02 geprüft. Neue Down-Gewichte sind tatsächlich verändert. Modellwachstum allein ersetzt keinen deutlich breiteren, geprüften Sprachkorpus.', '', '## Regressionstest', '| Bereich | 20M Preview 02 | 40M Trainingsversuch |','|---|---:|---:|']
    lines += [f'| {r["domain"]} | {r["before"]:.4f} | {r["after"]:.4f} |' for r in result['domains']]
    lines += ['', f'Macro-Test-Loss: {result["test"]["before"]:.4f} → {result["test"]["after"]:.4f}. Derselbe bereits betrachtete Testsatz; kein neuer unabhängiger Benchmark. Reine Modellrechnung: {raw["math_numeric_exact"]["correct"]}/{raw["math_numeric_exact"]["total"]} korrekt. Freie Chatantworten sind weiterhin oft unverständlich. Rohantworten bleiben in reports/neral40m_candidate_test.json erhalten.', '', '## Features V1 ausprobieren','Öffne http://127.0.0.1:9680 und klicke auf **Projekte → Beispiel ausprobieren**. Das Beispiel ist ausdrücklich eine lokale Budgetplanung, keine aus deinen privaten Dateien abgeleitete Analyse.', '', '1. **CASCADE:** Budget 1200 → 1600 als Vorschau anzeigen. Reserve, verfügbares Budget, Live-Antwort und Einkaufsliste werden als Folgen sichtbar. Erst „Änderungen bestätigen & anwenden“ speichert. Undo setzt Projektwerte zurück, ohne Versionsgeschichte zu löschen. Veraltete Vorschauen und doppeltes Anwenden werden blockiert.', '2. **RIPPLE:** Verfolgt alle hinterlegten Verbindungen über das gesamte gewählte Projekt. Zeigt betroffene Einträge, einen Pfad dorthin und ihre direkten Abhängigkeiten. V1 erkennt keine unangemeldeten Dateien oder impliziten Beziehungen.', '3. **SOLVE:** Eigener Modus für exakte Bruchrechnung, Potenzen und nun lineare Gleichungen: `2*x + 3 = 11` liefert `x = 4` mit Umformung und Probe. Nichtlineare Gleichungen werden klar abgewiesen; keine allgemeine Problemlösefähigkeit behauptet.', '4. **LIVING Answers:** Formeln und Antwortvorlagen als „Live“ markieren. Bestätigte Änderungen ihrer lokalen Quellen berechnen sie neu und speichern Version, Vorgängertext, Zeitpunkt und Änderungsgrund. Auch Undo erzeugt eine neue Version. Unveränderte Prüfungen erzeugen keine falsche neue Version. Daten und Historie bleiben in SQLite über Neustarts erhalten.', '', 'Eigene Projekte lassen sich anlegen; Annahmen, Formeln, Antwortvorlagen und Aufgaben hinzufügen. Formeln wie `budget * 0.1` und Vorlagen wie `Verfügbar: {{budget}} EUR` erzeugen Abhängigkeiten. Betroffene Aufgaben erhalten einen Prüfhinweis und können als geprüft markiert werden.', '', '**Umfang:** Diese Features sind lokale, deterministische Werkzeuge. Sie sind keine vom Neral-Modell zuverlässig erkannten oder gelernten Fähigkeiten. Live-Antworten reagieren auf Änderungen im gespeicherten Projekt; externe Webseiten werden nicht überwacht. Undo ist nur unmittelbar nach der letzten CASCADE-Transaktion möglich, damit spätere Arbeit nicht überschrieben wird.', '', '## Prüfung und Start',f'- {tests} automatisierte Tests, {failed} Fehler. Darunter atomare Vorschauen, Konflikte, projektübergreifende Trennung, Undo, Persistenz, Live-Versionen, 756 konstruierte lineare Gleichungen sowie bestehende Sicherheitsprüfungen.', '- JavaScript-Syntaxprüfungen durchgeführt. Browser-/HTTP-Prüfungen separat in reports/browser_qa_03.json und reports/live_http_03.json.', '- Start: START_NERAL.bat. Eigene 40M-Variante unter „Modell“ auswählbar; Warnung auf schlechtere Validierung sichtbar.', '- Lokale Projektdatei: local_state/projects.sqlite3. Trainings- und Modellartefakte liegen getrennt unter runs/, seed/ und export/.', '', '## Nachweise', '- reports/growth_40m.json und baseline_before_growth.json: gemessener Architekturvergleich.', '- runs/neral40m_01/ und runs/neral40m_capacity/: tatsächliche Messreihen, bester und letzter Checkpoint.', '- reports/capacity_integrity.json: Abstammung, Hashes und unveränderte übernommene Gewichte.', '- export/neral40m/neral40m.pt: tatsächlich trainierter experimenteller 40M-Kandidat.', '- seed/neral40m.pt: funktionsbewahrend erweiterter Ausgangszustand.', '- reports/comparison.json: aktuelle zusammengeführte Messwerte.']
    Path('PREVIEW_03.md').write_text('\n'.join(lines)+'\n',encoding='utf8');print(json.dumps({'parameters':40051200,'tests':tests,'failed':failed,'runs':{k:v['summary'] for k,v in runs.items()}},indent=2))
if __name__=='__main__':main()
